import https from 'https';
import { writeFileSync } from 'fs';

const URL = 'https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_10m_admin_0_countries.geojson';

const COUNTRIES = {
  DEU: { code: '12', name: 'Germany' },
  CZE: { code: '11', name: 'Czech Republic' },
  SVK: { code: '14', name: 'Slovakia' },
  HUN: { code: '18', name: 'Hungary' },
  SVN: { code: '10', name: 'Slovenia' },
  ITA: { code: '13', name: 'Italy' },
  CHE: { code: '17', name: 'Switzerland' },
  LIE: { code: '16', name: 'Liechtenstein' },
  HRV: { code: '15', name: 'Croatia' },
};

// Projection formulas
function projectLon(lon) {
  return (lon - 9.5009) / 7.6623 * 612.94;
}
function projectLat(lat) {
  return (49.0153 - lat) / 2.6440 * 313.55;
}

// Download with streaming
function download(url) {
  return new Promise((resolve, reject) => {
    console.error(`Downloading ${url}...`);
    const follow = (u) => {
      https.get(u, { headers: { 'User-Agent': 'node' } }, (res) => {
        if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
          console.error(`Redirecting to ${res.headers.location}`);
          follow(res.headers.location);
          return;
        }
        if (res.statusCode !== 200) {
          reject(new Error(`HTTP ${res.statusCode}`));
          return;
        }
        const chunks = [];
        let totalBytes = 0;
        res.on('data', (chunk) => {
          chunks.push(chunk);
          totalBytes += chunk.length;
          if (totalBytes % (5 * 1024 * 1024) < chunk.length) {
            console.error(`  Downloaded ${(totalBytes / 1024 / 1024).toFixed(1)} MB...`);
          }
        });
        res.on('end', () => {
          console.error(`  Download complete: ${(totalBytes / 1024 / 1024).toFixed(1)} MB`);
          resolve(Buffer.concat(chunks).toString('utf8'));
        });
        res.on('error', reject);
      }).on('error', reject);
    };
    follow(url);
  });
}

// Compute area of a ring (in projected coordinates) using shoelace formula
function ringArea(ring) {
  let area = 0;
  for (let i = 0; i < ring.length - 1; i++) {
    area += ring[i][0] * ring[i + 1][1];
    area -= ring[i + 1][0] * ring[i][1];
  }
  return Math.abs(area) / 2;
}

// Compute centroid of a ring
function ringCentroid(ring) {
  let cx = 0, cy = 0, area = 0;
  for (let i = 0; i < ring.length - 1; i++) {
    const cross = ring[i][0] * ring[i + 1][1] - ring[i + 1][0] * ring[i][1];
    cx += (ring[i][0] + ring[i + 1][0]) * cross;
    cy += (ring[i][1] + ring[i + 1][1]) * cross;
    area += cross;
  }
  area /= 2;
  if (Math.abs(area) < 1e-10) {
    // Degenerate, just average
    const avgX = ring.reduce((s, p) => s + p[0], 0) / ring.length;
    const avgY = ring.reduce((s, p) => s + p[1], 0) / ring.length;
    return [avgX, avgY];
  }
  cx /= (6 * area);
  cy /= (6 * area);
  return [cx, cy];
}

// Simplify a ring by skipping points (keep every nth point)
function simplifyRing(ring, factor) {
  if (ring.length <= 4) return ring; // too small to simplify
  const result = [];
  for (let i = 0; i < ring.length - 1; i++) {
    if (i % factor === 0) {
      result.push(ring[i]);
    }
  }
  // Always close the ring
  if (result.length > 0) {
    result.push(result[0]);
  }
  return result;
}

// Convert a list of rings to SVG path data
function ringsToPath(rings, skipFactor) {
  const parts = [];
  for (const ring of rings) {
    let pts = ring;
    if (skipFactor > 1) {
      pts = simplifyRing(ring, skipFactor);
    }
    if (pts.length < 3) continue;
    const projected = pts.map(([lon, lat]) => [
      Math.round(projectLon(lon) * 10) / 10,
      Math.round(projectLat(lat) * 10) / 10,
    ]);
    let d = `M${projected[0][0]},${projected[0][1]}`;
    for (let i = 1; i < projected.length; i++) {
      d += `L${projected[i][0]},${projected[i][1]}`;
    }
    d += 'Z';
    parts.push(d);
  }
  return parts.join(' ');
}

// Get all rings from a geometry (flattened)
function getAllRings(geometry) {
  const rings = [];
  if (geometry.type === 'Polygon') {
    for (const ring of geometry.coordinates) {
      rings.push(ring);
    }
  } else if (geometry.type === 'MultiPolygon') {
    for (const polygon of geometry.coordinates) {
      for (const ring of polygon) {
        rings.push(ring);
      }
    }
  }
  return rings;
}

// Get polygons as separate groups (each polygon = [exterior, ...holes])
function getPolygons(geometry) {
  const polygons = [];
  if (geometry.type === 'Polygon') {
    polygons.push(geometry.coordinates);
  } else if (geometry.type === 'MultiPolygon') {
    for (const polygon of geometry.coordinates) {
      polygons.push(polygon);
    }
  }
  return polygons;
}

// Visible area bounds (expanded viewBox)
const VIEW_MIN_X = -300;
const VIEW_MAX_X = 800;
const VIEW_MIN_Y = -120;
const VIEW_MAX_Y = 440;

// Clamp label to visible area with some margin
function clampLabel(x, y) {
  x = Math.max(VIEW_MIN_X + 30, Math.min(VIEW_MAX_X - 30, x));
  y = Math.max(VIEW_MIN_Y + 20, Math.min(VIEW_MAX_Y - 20, y));
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

async function main() {
  const raw = await download(URL);
  console.error('Parsing GeoJSON...');
  const geojson = JSON.parse(raw);
  console.error(`Parsed ${geojson.features.length} features`);

  const results = {};

  for (const feature of geojson.features) {
    const iso = feature.properties.ISO_A3 || feature.properties.ISO_A3_EH;
    if (!COUNTRIES[iso]) continue;

    const info = COUNTRIES[iso];
    console.error(`\nProcessing ${info.name} (${iso})...`);

    const geometry = feature.geometry;
    const allRings = getAllRings(geometry);
    const polygons = getPolygons(geometry);

    console.error(`  ${polygons.length} polygon(s), ${allRings.length} total ring(s)`);

    // Generate path with no simplification first
    let pathData = ringsToPath(allRings, 1);
    let simplFactor = 1;
    console.error(`  Raw path length: ${pathData.length} chars`);

    // If too large, simplify
    if (pathData.length > 50000) {
      // Try increasing skip factors
      for (const factor of [2, 3, 4, 5, 6, 8, 10]) {
        const simplified = ringsToPath(allRings, factor);
        console.error(`  Skip factor ${factor}: ${simplified.length} chars`);
        if (simplified.length <= 50000) {
          pathData = simplified;
          simplFactor = factor;
          break;
        }
        if (factor === 10) {
          pathData = simplified;
          simplFactor = factor;
        }
      }
      console.error(`  Using skip factor ${simplFactor}, final: ${pathData.length} chars`);
    }

    // Find largest polygon for label placement
    let largestArea = 0;
    let largestExterior = null;
    for (const polygon of polygons) {
      const exterior = polygon[0]; // first ring is exterior
      // Compute area in projected space
      const projRing = exterior.map(([lon, lat]) => [projectLon(lon), projectLat(lat)]);
      const area = ringArea(projRing);
      if (area > largestArea) {
        largestArea = area;
        largestExterior = projRing;
      }
    }

    let [labelX, labelY] = ringCentroid(largestExterior);
    console.error(`  Raw centroid: (${labelX.toFixed(1)}, ${labelY.toFixed(1)})`);

    // Clamp to visible area
    [labelX, labelY] = clampLabel(labelX, labelY);
    console.error(`  Clamped label: (${labelX}, ${labelY})`);

    results[info.code] = {
      d: pathData,
      labelX,
      labelY,
    };
  }

  // Check for missing countries (ISO_A3 might differ)
  const foundIsos = new Set();
  for (const feature of geojson.features) {
    const iso = feature.properties.ISO_A3 || feature.properties.ISO_A3_EH;
    if (COUNTRIES[iso]) foundIsos.add(iso);
  }
  for (const [iso, info] of Object.entries(COUNTRIES)) {
    if (!foundIsos.has(iso)) {
      console.error(`\nWARNING: ${info.name} (${iso}) not found! Trying alternate fields...`);
      // Try searching by name or other fields
      for (const feature of geojson.features) {
        const props = feature.properties;
        const nameMatch = (props.NAME || '').toLowerCase().includes(info.name.toLowerCase()) ||
          (props.NAME_LONG || '').toLowerCase().includes(info.name.toLowerCase()) ||
          (props.ADMIN || '').toLowerCase().includes(info.name.toLowerCase());
        const isoEH = props.ISO_A3_EH;
        if (nameMatch || isoEH === iso) {
          console.error(`  Found via alternate matching: ${props.NAME} / ${props.ISO_A3} / ${props.ISO_A3_EH}`);

          const geometry = feature.geometry;
          const allRings = getAllRings(geometry);
          const polygons = getPolygons(geometry);

          let pathData = ringsToPath(allRings, 1);
          if (pathData.length > 50000) {
            for (const factor of [2, 3, 4, 5, 6, 8, 10]) {
              const simplified = ringsToPath(allRings, factor);
              if (simplified.length <= 50000) {
                pathData = simplified;
                break;
              }
              if (factor === 10) pathData = simplified;
            }
          }
          console.error(`  Path length: ${pathData.length} chars`);

          let largestArea = 0;
          let largestExterior = null;
          for (const polygon of polygons) {
            const exterior = polygon[0];
            const projRing = exterior.map(([lon, lat]) => [projectLon(lon), projectLat(lat)]);
            const area = ringArea(projRing);
            if (area > largestArea) {
              largestArea = area;
              largestExterior = projRing;
            }
          }

          let [labelX, labelY] = ringCentroid(largestExterior);
          [labelX, labelY] = clampLabel(labelX, labelY);

          results[info.code] = { d: pathData, labelX, labelY };
          break;
        }
      }
    }
  }

  // Print summary
  console.error('\n=== SUMMARY ===');
  for (const [code, data] of Object.entries(results).sort((a, b) => a[0].localeCompare(b[0]))) {
    const countryName = Object.values(COUNTRIES).find(c => c.code === code)?.name || '?';
    console.error(`  ${code} (${countryName}): path=${data.d.length} chars, label=(${data.labelX}, ${data.labelY})`);
  }

  // Output TypeScript
  console.log('// Auto-generated from Natural Earth 10m data');
  console.log('// Projection: svgX = (lon - 9.5009) / 7.6623 * 612.94');
  console.log('//             svgY = (49.0153 - lat) / 2.6440 * 313.55');
  console.log('');
  console.log('export const neighborPaths: Record<string, { d: string; labelX: number; labelY: number }> = {');

  for (const [code, data] of Object.entries(results).sort((a, b) => a[0].localeCompare(b[0]))) {
    const countryName = Object.values(COUNTRIES).find(c => c.code === code)?.name || '?';
    console.log(`  // ${countryName} — ${data.d.length} chars`);
    console.log(`  "${code}": {`);
    console.log(`    d: "${data.d}",`);
    console.log(`    labelX: ${data.labelX},`);
    console.log(`    labelY: ${data.labelY},`);
    console.log(`  },`);
  }

  console.log('};');
}

main().catch((err) => {
  console.error('FATAL:', err);
