  }

  // Second pass: try ISO_A3_EH for anything missing
  for (const [iso, info] of Object.entries(COUNTRIES)) {
    if (results[info.code]) continue;
    for (const feature of geojson.features) {
      if (feature.properties.ISO_A3_EH === iso) {
        console.error(`\nProcessing ${info.name} (${iso}) via ISO_A3_EH...`);
        results[info.code] = processFeature(feature, info);
        break;
      }
    }
  }

  // Third pass: try name matching for anything still missing
  for (const [iso, info] of Object.entries(COUNTRIES)) {
    if (results[info.code]) continue;
