// Simplify neighbor country paths from Natural Earth 10m GeoJSON
// Uses Douglas-Peucker simplification after projecting to SVG coordinates

import { writeFileSync } from 'fs';

const GEOJSON_URL = 'https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_10m_admin_0_countries.geojson';

const COUNTRIES = {
  DEU: '12', CZE: '11', SVK: '14', HUN: '18',
  SVN: '10', ITA: '13', CHE: '17', LIE: '16', HRV: '15'
};

const LABELS = {
  '12': { labelX: 70, labelY: -50 },
  '11': { labelX: 465, labelY: -85 },
  '14': { labelX: 770, labelY: 37 },
  '18': { labelX: 770, labelY: 220 },
  '10': { labelX: 425, labelY: 345 },
  '13': { labelX: 150, labelY: 380 },
  '17': { labelX: -100, labelY: 263 },
  '16': { labelX: 4, labelY: 222 },
  '15': { labelX: 555, labelY: 420 },
};

// Projection: lon/lat -> SVG coordinates
function projectX(lon) {
  return (lon - 9.5009) / 7.6623 * 612.94;
}

function projectY(lat) {
  return (49.0153 - lat) / 2.6440 * 313.55;
}

// Perpendicular distance from point to line segment
function perpendicularDist(px, py, ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  const lenSq = dx * dx + dy * dy;
  if (lenSq === 0) {
    const ex = px - ax;
    const ey = py - ay;
    return Math.sqrt(ex * ex + ey * ey);
  }
  // Area of triangle * 2 / base length
  const area2 = Math.abs(dx * (ay - py) - (ax - px) * dy);
  return area2 / Math.sqrt(lenSq);
}

// Douglas-Peucker simplification
function simplify(points, tolerance) {
  if (points.length <= 2) return points;

  let maxDist = 0;
  let maxIdx = 0;
  const first = points[0];
  const last = points[points.length - 1];

  for (let i = 1; i < points.length - 1; i++) {
    const d = perpendicularDist(
      points[i][0], points[i][1],
      first[0], first[1],
      last[0], last[1]
    );
    if (d > maxDist) {
      maxDist = d;
      maxIdx = i;
    }
  }

  if (maxDist > tolerance) {
    const left = simplify(points.slice(0, maxIdx + 1), tolerance);
    const right = simplify(points.slice(maxIdx), tolerance);
    return left.concat(right.slice(1));
  } else {
    return [first, last];
  }
}

// Check if a ring is entirely outside the visible area
function isOutsideVisible(ring) {
  const xMin = -350, xMax = 850, yMin = -200, yMax = 500;
  for (const [x, y] of ring) {
    if (x >= xMin && x <= xMax && y >= yMin && y <= yMax) {
      return false;
    }
  }
  return true;
}

// Get bounding box dimensions
function getBBox(ring) {
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const [x, y] of ring) {
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  return { width: maxX - minX, height: maxY - minY };
}

// Convert rings to SVG path string
function ringsToPath(rings) {
  const parts = [];
  for (const ring of rings) {
    if (ring.length === 0) continue;
    const coords = ring.map(([x, y]) => `${x},${y}`);
    parts.push('M' + coords.join('L') + 'Z');
  }
  return parts.join('');
}

// Round a point to 1 decimal place
function roundPt(pt) {
  return [Math.round(pt[0] * 10) / 10, Math.round(pt[1] * 10) / 10];
}

async function main() {
  console.log('Fetching 10m GeoJSON...');
  const resp = await fetch(GEOJSON_URL);
  if (!resp.ok) throw new Error(`Fetch failed: ${resp.status}`);
  const geojson = await resp.json();
  console.log(`Loaded ${geojson.features.length} features`);

  const results = {};

  for (const [iso, code] of Object.entries(COUNTRIES)) {
    const feature = geojson.features.find(f =>
      f.properties.ISO_A3 === iso || f.properties.ISO_A3_EH === iso
    );
    if (!feature) {
      console.warn(`Country not found: ${iso}`);
      continue;
    }

    console.log(`Processing ${iso} (${code}): ${feature.geometry.type}`);

    // Collect all polygon rings
    let polygons = [];
    if (feature.geometry.type === 'Polygon') {
      polygons = [feature.geometry.coordinates];
    } else if (feature.geometry.type === 'MultiPolygon') {
      polygons = feature.geometry.coordinates;
    }

    const allRings = [];

    for (const polygon of polygons) {
      const projectedRings = [];

      for (let ri = 0; ri < polygon.length; ri++) {
        const ring = polygon[ri];
        // Project to SVG coordinates
        const projected = ring.map(([lon, lat]) => [projectX(lon), projectY(lat)]);

        // Check if this is a tiny island (check outer ring = first ring only)
        if (ri === 0) {
          const bbox = getBBox(projected);
          if (bbox.width < 15 && bbox.height < 15) {
            // Skip entire polygon (tiny island)
            break;
          }
        }

        // Choose tolerance based on visibility
        const tolerance = isOutsideVisible(projected) ? 5.0 : 2.0;

        // Simplify
        let simplified = simplify(projected, tolerance);

        // Round to 1 decimal place
        simplified = simplified.map(roundPt);

        // Only keep rings with at least 3 points (valid polygon)
        if (simplified.length >= 3) {
          projectedRings.push(simplified);
        }
      }

      if (projectedRings.length > 0) {
        allRings.push(...projectedRings);
      }
    }

    const pathD = ringsToPath(allRings);
    results[code] = {
      d: pathD,
      ...LABELS[code]
    };
  }

  // Build output
  let output = `// Auto-generated from Natural Earth 10m data (simplified)
// Projection: svgX = (lon - 9.5009) / 7.6623 * 612.94
//             svgY = (49.0153 - lat) / 2.6440 * 313.55
// Douglas-Peucker tolerance: 2.0 SVG units (5.0 for off-screen rings)

export const neighborPaths: Record<string, { d: string; labelX: number; labelY: number }> = {\n`;

  let totalChars = 0;

  // Sort by code for consistent output
  const sortedCodes = Object.keys(results).sort((a, b) => parseInt(a) - parseInt(b));

  for (const code of sortedCodes) {
    const { d, labelX, labelY } = results[code];
    const isoName = Object.entries(COUNTRIES).find(([, c]) => c === code)[0];
    const entry = `  // ${isoName} - ${d.length} chars
  "${code}": {
    d: "${d}",
    labelX: ${labelX},
    labelY: ${labelY},
  },\n`;
    output += entry;
    console.log(`  ${code} (${isoName}): ${d.length} chars path`);
    totalChars += d.length;
  }

  output += `};\n`;

  writeFileSync('/tmp/neighbor_paths_simplified.ts', output);

  console.log(`\nTotal path chars: ${totalChars}`);
  console.log(`Output file size: ${output.length} chars`);
  console.log(`Written to /tmp/neighbor_paths_simplified.ts`);
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
SCRIPT_EOF
