   131→  text += `Rapporte gesamt: ${stats.reports}\n\n`;
   132→  text += 'Pro Frequenz:\n';
   133→  for (const r of perRepeater) {
   134→    text += `  ${r.short_name.padEnd(25)} ${r.count}\n`;
   135→  }
   136→  text += '\n';
   137→
   138→  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
   139→  res.setHeader('Content-Disposition', `attachment; filename="bos-arsa-combined-${safeFilename(exercise.date)}.txt"`);
