    29→function getQuarter(date: string): number {
    30→  const month = new Date(date + 'T00:00:00').getMonth();
    31→  return Math.floor(month / 3) + 1;
    32→}
    33→
    34→export default function DashboardPage() {
    35→  const { admin } = useAuth();
    36→  const navigate = useNavigate();
    37→  const [exercises, setExercises] = useState<ExerciseSummary[]>([]);
    38→  const [loading, setLoading] = useState(true);
    39→  const [showCreate, setShowCreate] = useState(false);
    40→  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
    41→  const [newName, setNewName] = useState(EXERCISE_TYPES[0]);
    42→  const [creating, setCreating] = useState(false);
    43→
    44→  useEffect(() => {
    45→    apiFetch('/api/v1/exercises')
    46→      .then(data => setExercises(data))
    47→      .catch(() => {})
    48→      .finally(() => setLoading(false));
    49→  }, []);
    50→
    51→  const formatDate = (d: string) => {
    52→    const date = new Date(d + 'T00:00:00');
    53→    return date.toLocaleDateString('de-AT', { weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
    54→  };
    55→
    56→  // Compute nearest exercise today or in the future
    57→  const today = new Date().toISOString().split('T')[0];
    58→  const futureExercises = exercises.filter(e => e.date >= today);
    59→  const nearestId = futureExercises.length > 0
    60→    ? futureExercises.reduce((closest, e) => {
    61→        const dCur = new Date(e.date).getTime() - new Date(today).getTime();
    62→        const dBest = new Date(closest.date).getTime() - new Date(today).getTime();
    63→        return dCur < dBest ? e : closest;
    64→      }, futureExercises[0]).id
    65→    : null;
    66→
    67→  // Compute quarterly and yearly totals
    68→  const quarterTotals: Record<number, { participants: number; reports: number }> = {};
    69→  let yearParticipants = 0;
    70→  let yearReports = 0;
    71→
    72→  for (const ex of exercises) {
    73→    const q = getQuarter(ex.date);
    74→    if (!quarterTotals[q]) quarterTotals[q] = { participants: 0, reports: 0 };
    75→    quarterTotals[q].participants += ex.participant_count;
    76→    quarterTotals[q].reports += ex.report_count;
